class Skiplist {
  private static final int MAX_LEVEL = 16;
  private final Node head = new Node(-1, MAX_LEVEL);
  private int level = 1;

  private static class Node {
    final int val;
    final Node[] next;

    Node(int val, int levels) {
      this.val = val;
      this.next = new Node[levels];
    }
  }

  public boolean search(int target) {
    Node cur = head;
    for (int i = level - 1; i >= 0; i--)
      while (cur.next[i] != null && cur.next[i].val < target) cur = cur.next[i];
    cur = cur.next[0];
    return cur != null && cur.val == target;
  }

  public void add(int num) {
    Node[] update = predecessors(num);
    int levels = randomLevel();
    if (levels > level) {
      for (int i = level; i < levels; i++) update[i] = head;
      level = levels;
    }
    Node node = new Node(num, levels);
    for (int i = 0; i < levels; i++) {
      node.next[i] = update[i].next[i];
      update[i].next[i] = node;
    }
  }

  public boolean erase(int num) {
    Node[] update = predecessors(num);
    Node target = update[0].next[0];
    if (target == null || target.val != num) return false;
    for (int i = 0; i < level && update[i].next[i] == target; i++) update[i].next[i] = target.next[i];
    while (level > 1 && head.next[level - 1] == null) level--;
    return true;
  }

  // the last node before `num` on every level
  private Node[] predecessors(int num) {
    Node[] update = new Node[MAX_LEVEL];
    Node cur = head;
    for (int i = level - 1; i >= 0; i--) {
      while (cur.next[i] != null && cur.next[i].val < num) cur = cur.next[i];
      update[i] = cur;
    }
    return update;
  }

  // each extra level with probability 1/2, which gives the expected O(log n) per operation
  private int randomLevel() {
    int levels = 1;
    while (levels < MAX_LEVEL && Math.random() < 0.5) levels++;
    return levels;
  }
}
